package kome.common.data;

import java.util.*;
import lotr.common.entity.npc.LOTREntityNPC;
import net.minecraftforge.event.entity.living.LivingEvent;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;
import static kome.common.data.KOMEKnightCommission.*;

/** Every concrete scenario executes the same lifecycle contract, using live inert world actors. */
@RunWith(Parameterized.class)
public class KOMELordshipTrialGameplayTest {
    @Parameterized.Parameters(name="{0}") public static Collection<Object[]> scenarios(){List<Object[]> rows=new ArrayList<Object[]>();for(KOMELordshipTrial.Scenario s:KOMELordshipTrial.Scenario.values())rows.add(new Object[]{s});return rows;}
    private final KOMELordshipTrial.Scenario scenario;
    public KOMELordshipTrialGameplayTest(KOMELordshipTrial.Scenario scenario){this.scenario=scenario;}
    private KOMELordshipTrial active(KOMELordshipTrialFixture f)throws Exception {
        KOMELordshipTrial t=f.trial(scenario,Stage.ACTIVE);f.atSite(t);f.force(t);t.objective.encounterCreated=true;
        if(scenario!=KOMELordshipTrial.Scenario.BORDER_PATROL)f.actor(t,scenario==KOMELordshipTrial.Scenario.PROTECTED_EXPEDITION?Role.CHARGE:Role.BENEFICIARY);
        return t;
    }
    private void arrive(KOMELordshipTrialFixture f,KOMELordshipTrial t){
        if(scenario!=KOMELordshipTrial.Scenario.PROTECTED_EXPEDITION)return;
        f.s.f.player.posX=t.objective.destinationX;f.s.f.player.posZ=t.objective.destinationZ;
        for(Actor actor:t.objective.actors)if(actor.role!=Role.ENEMY&&!actor.dead){LOTREntityNPC npc=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,actor.id);npc.posX=f.s.f.player.posX;npc.posZ=f.s.f.player.posZ;}
    }
    @Test public void destinationAloneNeverResolvesThreat()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);f.actor(t,Role.ENEMY);arrive(f,t);KOMELordshipTrialService.tickPlayer(f.s.f.player);assertEquals(Stage.ACTIVE,t.objective.stage);}}
    @Test public void alliedFinishingKillsProduceReadyAfterOwnerParticipation()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);LOTREntityNPC enemy=f.actor(t,Role.ENEMY);assertTrue(KOMELordshipTrialService.noteDamage(f.s.f.data,f.s.f.player.id,enemy.getUniqueID().toString()));f.kill(enemy);arrive(f,t);KOMELordshipTrialService.tickPlayer(f.s.f.player);assertEquals(Stage.READY_TO_REPORT,t.objective.stage);assertEquals(KOMEProgressionRank.KNIGHT,f.s.p.getCanonicalRank());assertTrue(f.s.p.getKnightService().completedTypes().isEmpty());}}
    @Test public void noOwnerContributionFailsWhenAlliesSolveEncounter()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);f.kill(f.actor(t,Role.ENEMY));assertEquals(Stage.FAILED,t.objective.stage);}}
    @Test public void absentOwnerCannotEarnCreditFromAllies()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);LOTREntityNPC enemy=f.actor(t,Role.ENEMY);KOMELordshipTrialService.noteDamage(f.s.f.data,f.s.f.player.id,enemy.getUniqueID().toString());f.s.f.player.posX+=300;f.kill(enemy);assertEquals(Stage.FAILED,t.objective.stage);}}
    @Test public void exactlyHalfSurvivingForceIsEnough()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);List<Actor> guards=new ArrayList<Actor>(t.objective.actors);for(int i=0;i<2;i++)f.kill((LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,guards.get(i).id));LOTREntityNPC enemy=f.actor(t,Role.ENEMY);KOMELordshipTrialService.noteDamage(f.s.f.data,f.s.f.player.id,enemy.getUniqueID().toString());f.kill(enemy);arrive(f,t);KOMELordshipTrialService.tickPlayer(f.s.f.player);assertTrue(t.ready());assertEquals(2,t.confirmedSurvivors());}}
    @Test public void tooManyConfirmedDeathsFailAndCleanWithoutDemotion()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){f.credits(3);KOMELordshipTrial t=active(f);List<Actor> guards=new ArrayList<Actor>(t.objective.actors);for(int i=0;i<3;i++)f.kill((LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,guards.get(i).id));assertEquals(Stage.FAILED,t.objective.stage);assertEquals("casualties",t.failureReason);assertEquals(3,f.s.p.getKnightService().completedTypes().size());assertEquals(KOMEProgressionRank.KNIGHT,f.s.p.getCanonicalRank());for(Actor actor:t.objective.actors){LOTREntityNPC npc=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,actor.id);assertTrue(npc.isDead);assertFalse(npc.hiredNPCInfo.isActive);assertFalse(KOMEProgressionNpcRoles.protects(f.s.f.data,npc.getUniqueID()));}}}
    @Test public void unloadIsNeitherDeathNorSuccessAndRejoinRetainsRole()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);LOTREntityNPC guard=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,t.objective.actors.get(0).id);f.s.f.world.loadedEntityList.removeIf(e->e==guard);f.s.chunks=false;f.s.reload();t=f.s.p.getLordship().assignment();KOMELordshipTrialService.tickPlayer(f.s.f.player);assertEquals(Stage.ACTIVE,t.objective.stage);assertEquals(4,t.confirmedSurvivors());f.s.f.world.loadedEntityList.add(guard);KOMELordshipTrialService.reconcileNpc(f.s.f.data,guard);assertTrue(KOMELordshipTrialService.temporaryFollower(f.s.f.data,guard));}}
    @Test public void missingSurvivorCannotBeCertifiedAndEventuallyAllowsRetry()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);LOTREntityNPC guard=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,t.objective.actors.get(0).id);f.s.f.world.loadedEntityList.removeIf(e->e==guard);for(int i=0;i<60;i++)KOMELordshipTrialService.tickPlayer(f.s.f.player);assertEquals(Stage.FAILED,t.objective.stage);assertEquals("missing",t.failureReason);assertEquals(4,t.confirmedSurvivors());}}
    @Test public void activeTroopsBypassOrdinaryHireRegistrationAndEnforcement()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);for(Actor actor:t.objective.actors)if(actor.role==Role.GUARD){LOTREntityNPC n=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,actor.id);assertTrue(KOMESerfKnightEscortService.isActiveEscort(f.s.f.data,n));new KOMEEvents().onLivingUpdate(new LivingEvent.LivingUpdateEvent(n));assertFalse(n.isDead);assertTrue(n.hiredNPCInfo.isActive);}assertTrue(f.s.f.data.hiredUnits.isEmpty());}}
    @Test public void cancellationDismissesAndReleasesAllGeneratedActors()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);KOMEProgressionNpcRoles.syncPlayer(f.s.f.data,f.s.f.player.id);KOMELordshipTrialService.cancel(f.s.f.world,f.s.f.player.id,f.s.p);assertEquals(Stage.FAILED,t.objective.stage);for(Actor actor:t.objective.actors){LOTREntityNPC npc=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,actor.id);assertTrue(npc.isDead);assertFalse(npc.hiredNPCInfo.isActive);assertFalse(KOMEProgressionNpcRoles.protects(f.s.f.data,npc.getUniqueID()));}}}
    @Test public void successfulFieldCompletionRetainsGuardChargeUntilFormalReport()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){KOMELordshipTrial t=active(f);LOTREntityNPC enemy=f.actor(t,Role.ENEMY);KOMELordshipTrialService.noteDamage(f.s.f.data,f.s.f.player.id,enemy.getUniqueID().toString());f.kill(enemy);arrive(f,t);KOMELordshipTrialService.tickPlayer(f.s.f.player);assertTrue(t.ready());for(Actor actor:t.objective.actors){LOTREntityNPC npc=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,actor.id);if(actor.role==Role.GUARD){assertFalse(npc.isDead);assertTrue(npc.hiredNPCInfo.isActive);assertTrue(KOMEProgressionNpcRoles.protects(f.s.f.data,npc.getUniqueID()));}else{assertTrue(npc.isDead);assertFalse(npc.hiredNPCInfo.isActive);assertFalse(KOMEProgressionNpcRoles.protects(f.s.f.data,npc.getUniqueID()));}}}}
    @Test public void reportPromotesEverySuccessfulScenarioWithExistingAuthority()throws Exception {try(KOMELordshipTrialFixture f=new KOMELordshipTrialFixture()){f.credits(3);KOMELordshipTrial t=active(f);LOTREntityNPC enemy=f.actor(t,Role.ENEMY);KOMELordshipTrialService.noteDamage(f.s.f.data,f.s.f.player.id,enemy.getUniqueID().toString());f.kill(enemy);arrive(f,t);KOMELordshipTrialService.tickPlayer(f.s.f.player);assertTrue(t.ready());f.s.f.player.posX=f.liege.posX;f.s.f.player.posZ=f.liege.posZ;for(Actor a:t.objective.actors)if(a.role==Role.GUARD&&!a.dead){LOTREntityNPC n=(LOTREntityNPC)KOMEKnightCommissionService.findLoaded(f.s.f.world,a.id);n.posX=f.liege.posX;n.posZ=f.liege.posZ;}assertTrue(KOMELordshipTrialService.acceptOrReport(f.s.f.player,f.liege));assertEquals(KOMEProgressionRank.LORD,f.s.p.getCanonicalRank());assertNull(f.s.p.getLordship().assignment());assertEquals(Stage.REPORTED,f.s.p.getLordship().history().get(0).objective.stage);assertTrue(KOMEProgressionPermissions.has(f.s.f.player,KOMEProgressionPermissions.TAKE_WAYPOINTS));assertTrue(KOMEProgressionPermissions.has(f.s.f.player,KOMEProgressionPermissions.RECLAIM_WAYPOINTS));assertTrue(f.s.p.getSerfKnightProgression().hasLiege());}}
}
